"""Temporally-Decayed Confusion Memory.

Extends adaptive_tokenizer_confusion_memory with one structural change to the
learning strategy (axis E): confusion counts decay exponentially after each
training step, so the confusion matrix reflects the model's *current* error
patterns rather than its entire accumulated history.

Problem with the baseline: confusion counts are monotonically increasing integers.
A label pair confused heavily early in training (when the model had few examples)
accumulates a large count that permanently dominates disambiguation slot selection,
even after the model has seen dozens of corrective examples and stopped making
that mistake. The disambiguation phase keeps injecting examples for a boundary
the model no longer needs.

Fix: after each learn_from_batch call, multiply every existing confusion count by
DECAY_FACTOR (< 1). New error events are added with weight 1.0. Counts that decay
below a threshold are pruned to keep the matrix sparse. This gives recent errors
higher relative weight without requiring explicit timestamps.

Retrieval algorithm is identical to adaptive_tokenizer_confusion_memory (two-phase:
confusion slots then similarity fill) so any delta is attributable purely to the
decay mechanism. Also includes the prediction-normalization fix.
"""

import json
import re
from collections import defaultdict
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field

PROMPT_TEMPLATE = """Solve the problem below based on the examples provided.

{examples_section}

**Problem:**
{input}

**Instructions:**
- Follow the patterns shown in the examples above
- Respond in JSON format

{{"reasoning": "[your reasoning]", "final_answer": "[your answer]"}}"""

MAX_CHARS = 30000
_TOP_CANDIDATE_LABELS = 3
_DISAMBIG_PER_CONFUSION = 2

DECAY_FACTOR = 0.95      # multiply all counts after each step
PRUNE_THRESHOLD = 0.05   # drop entries with count below this

_CJK_RE = re.compile(r'[一-鿿぀-ゟ゠-ヿ＀-￯]')
_WRAPPER_RE = re.compile(r'^\s*\[[^\]]*\]|<eoa>\s*$|\[[^\]]*\]\s*$', re.IGNORECASE)


def _has_cjk(text: str) -> bool:
    return bool(_CJK_RE.search(text))


def _tokenize_word(text: str) -> frozenset:
    return frozenset(re.findall(r"[A-Za-z0-9]+", text.lower()))


def _tokenize_bigram(text: str) -> frozenset:
    t = re.sub(r'\s+', ' ', text.strip())
    if len(t) < 2:
        return frozenset([t]) if t else frozenset()
    return frozenset(t[i:i + 2] for i in range(len(t) - 1))


def _tokenize_adaptive(text: str) -> frozenset:
    return _tokenize_bigram(text) if _has_cjk(text) else _tokenize_word(text)


def _jaccard(a: frozenset, b: frozenset) -> float:
    if not a and not b:
        return 0.0
    return len(a & b) / len(a | b)


def _normalize_prediction(pred: str) -> str:
    """Strip format wrappers so predictions match ground-truth label strings."""
    if not pred:
        return pred
    cleaned = _WRAPPER_RE.sub('', pred).strip()
    return cleaned if cleaned else pred


class DecayedConfusionMemory(MemorySystem):
    """Adaptive-tokenizer confusion memory with exponentially-decayed confusion counts."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, Any]] = []
        # Float-valued counts to allow decay
        self.confusion: dict[str, dict[str, float]] = defaultdict(lambda: defaultdict(float))

    def _scored(self, query: str) -> list[tuple[float, int, dict]]:
        q_tok = _tokenize_adaptive(query)
        result = [
            (_jaccard(q_tok, ex["tokens"]), idx, ex)
            for idx, ex in enumerate(self.examples)
        ]
        result.sort(key=lambda x: (x[0], x[1]), reverse=True)
        return result

    def _confusion_targets_for(self, labels: list[str]) -> list[str]:
        label_set = set(labels)
        counts: dict[str, float] = defaultdict(float)
        for lbl in labels:
            row = self.confusion.get(lbl, {})
            for actual, cnt in row.items():
                if actual not in label_set:
                    counts[actual] += cnt
        return [lbl for lbl, _ in sorted(counts.items(), key=lambda x: (-x[1], x[0]))]

    def _build_parts(self, query: str) -> list[str]:
        if not self.examples:
            return []

        ranked = self._scored(query)
        top_labels = [ex["target"] for _, _, ex in ranked[:_TOP_CANDIDATE_LABELS]]
        confused_with = self._confusion_targets_for(top_labels)

        parts: list[str] = []
        used_indices: set[int] = set()
        total_chars = 0

        def try_add(idx: int, ex: dict) -> bool:
            nonlocal total_chars
            if idx in used_indices:
                return False
            q = ex.get("raw_question", ex["input"])
            part = f"Q: {q}\nA: {ex['target']}"
            if total_chars + len(part) + 2 > MAX_CHARS:
                return False
            parts.append(part)
            used_indices.add(idx)
            total_chars += len(part) + 2
            return True

        if confused_with:
            disambig_labels_needed = set(confused_with[:_TOP_CANDIDATE_LABELS])
            per_label_disambig: dict[str, list[tuple[float, int, dict]]] = defaultdict(list)
            for score, idx, ex in ranked:
                if ex["target"] in disambig_labels_needed:
                    per_label_disambig[ex["target"]].append((score, idx, ex))

            for _round in range(_DISAMBIG_PER_CONFUSION):
                for lbl in confused_with[:_TOP_CANDIDATE_LABELS]:
                    pool = per_label_disambig.get(lbl, [])
                    for score, idx, ex in pool:
                        if idx not in used_indices:
                            try_add(idx, ex)
                            break

        for _, idx, ex in ranked:
            if total_chars >= MAX_CHARS:
                break
            try_add(idx, ex)

        return parts

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        parts = self._build_parts(input)
        examples_section = "\n\n".join(parts)
        prompt = PROMPT_TEMPLATE.format(
            examples_section=examples_section,
            input=input,
        )
        response = self.call_llm(prompt)
        answer = extract_json_field(response, "final_answer")
        return answer, {
            "full_response": response,
            "num_examples": len(self.examples),
            "num_selected": len(parts),
            "num_confusion_pairs": sum(len(v) for v in self.confusion.values()),
        }

    def _decay_confusion(self) -> None:
        """Multiply all confusion counts by DECAY_FACTOR and prune near-zero entries."""
        to_delete_outer = []
        for pred, actuals in self.confusion.items():
            to_delete_inner = []
            for actual in actuals:
                actuals[actual] *= DECAY_FACTOR
                if actuals[actual] < PRUNE_THRESHOLD:
                    to_delete_inner.append(actual)
            for actual in to_delete_inner:
                del actuals[actual]
            if not actuals:
                to_delete_outer.append(pred)
        for pred in to_delete_outer:
            del self.confusion[pred]

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for r in batch_results:
            raw_q = r.get("raw_question", r["input"])
            ex: dict[str, Any] = {
                "input": r["input"],
                "target": r["ground_truth"],
                "tokens": _tokenize_adaptive(raw_q),
            }
            if "raw_question" in r:
                ex["raw_question"] = r["raw_question"]
            self.examples.append(ex)

            if not r.get("was_correct", True):
                pred = _normalize_prediction(r.get("prediction", ""))
                gt = r["ground_truth"]
                if pred and pred != gt:
                    self.confusion[pred][gt] += 1.0

        # Decay after processing the full batch
        self._decay_confusion()

    def get_state(self) -> str:
        serialisable = [
            {k: (sorted(v) if isinstance(v, frozenset) else v) for k, v in ex.items()}
            for ex in self.examples
        ]
        confusion_plain = {k: dict(v) for k, v in self.confusion.items()}
        return json.dumps({"examples": serialisable, "confusion": confusion_plain}, indent=2)

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.examples = []
        for ex in data.get("examples", []):
            restored = dict(ex)
            if "tokens" in restored and isinstance(restored["tokens"], list):
                restored["tokens"] = frozenset(restored["tokens"])
            else:
                raw_q = restored.get("raw_question", restored.get("input", ""))
                restored["tokens"] = _tokenize_adaptive(raw_q)
            self.examples.append(restored)
        self.confusion = defaultdict(lambda: defaultdict(float))
        for pred, actuals in data.get("confusion", {}).items():
            for actual, cnt in actuals.items():
                self.confusion[pred][actual] = float(cnt)

"""Hard-Example Buffer Memory.

Augments the decayed_confusion_memory general pool with a structurally separate
bounded FIFO buffer of error examples.

Problem with confusion-based systems: the confusion matrix is a sparse count over
label pairs — it records *which* labels are confused but stores no retrievable text
for the confused cases.  Examples of confusable inputs are sitting in the general
pool but are retrieved only if they happen to be similar to the current query; there
is no mechanism that preferentially surfaces examples that the model historically
mis-predicted.

Fix: every example where was_correct=False is also appended to a bounded hard
buffer (max HARD_BUFFER_SIZE entries, FIFO eviction).  At predict time, score
hard-buffer examples against the query with adaptive Jaccard and inject the top
HARD_SLOTS examples that exceed HARD_SIM_THRESHOLD similarity before filling the
rest of the context from the general pool.  The similarity gate prevents injecting
unrelated error examples that would dilute context quality.

This differs from utility_weighted_memory (which applied per-example outcome scores
to general-pool retrieval) because errors are held in a physically separate pool with
independent eviction; it differs from contrastive_error_memory (which stored explicit
wrong/correct pairs) because the prompt structure is unchanged — only the retrieval
source differs.

Memory-structure axis D + selection-algorithm axis C.
"""

import json
import re
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field

PROMPT_TEMPLATE = """Solve the problem below based on the examples provided.

{examples_section}

**Problem:**
{input}

**Instructions:**
- Follow the patterns shown in the examples above
- Respond in JSON format

{{"reasoning": "[your reasoning]", "final_answer": "[your answer]"}}"""

MAX_CHARS = 30000
_HARD_BUFFER_SIZE = 60      # maximum error examples retained (FIFO eviction)
_HARD_SLOTS = 3             # max hard-buffer examples injected per query
_HARD_SIM_THRESHOLD = 0.10  # minimum Jaccard similarity to inject a hard example
_TOP_CANDIDATE_LABELS = 3   # top retrieved labels used to query confusion matrix
_DISAMBIG_PER_CONFUSION = 2 # rounds of confusion-slot injection
DECAY_FACTOR = 0.95         # multiply confusion counts after each batch
_DECAY_FACTOR = DECAY_FACTOR
_PRUNE_THRESHOLD = 0.05     # drop confusion entries below this count

_CJK_RE = re.compile(r'[一-鿿぀-ゟ゠-ヿ＀-￯]')
_WRAPPER_RE = re.compile(r'^\s*\[[^\]]*\]|<eoa>\s*$|\[[^\]]*\]\s*$', re.IGNORECASE)


def _has_cjk(text: str) -> bool:
    return bool(_CJK_RE.search(text))


def _tokenize_word(text: str) -> frozenset:
    return frozenset(re.findall(r"[A-Za-z0-9]+", text.lower()))


def _tokenize_bigram(text: str) -> frozenset:
    t = re.sub(r'\s+', ' ', text.strip())
    if len(t) < 2:
        return frozenset([t]) if t else frozenset()
    return frozenset(t[i:i + 2] for i in range(len(t) - 1))


def _tokenize_adaptive(text: str) -> frozenset:
    return _tokenize_bigram(text) if _has_cjk(text) else _tokenize_word(text)


def _jaccard(a: frozenset, b: frozenset) -> float:
    if not a and not b:
        return 0.0
    return len(a & b) / len(a | b)


def _normalize_prediction(pred: str) -> str:
    if not pred:
        return pred
    cleaned = _WRAPPER_RE.sub('', pred).strip()
    return cleaned if cleaned else pred


class HardBufferMemory(MemorySystem):
    """Decayed confusion memory augmented with a structurally separate hard-example buffer.

    At predict time, the hard buffer is scored against the query and its top
    HARD_SLOTS most-similar examples (above HARD_SIM_THRESHOLD) are injected
    before the general similarity fill.  This ensures examples from error-
    producing inputs are preferentially surfaced when a new query resembles them,
    without the fragile exact-key lookup that confusion-matrix systems require.
    The confusion matrix is retained for additional disambiguation slots.
    """

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, Any]] = []
        # Bounded hard buffer: examples where was_correct=False (FIFO)
        self._hard: list[dict[str, Any]] = []
        self.confusion: dict[str, dict[str, float]] = defaultdict(lambda: defaultdict(float))

    # ------------------------------------------------------------------
    # Retrieval helpers
    # ------------------------------------------------------------------

    def _scored(self, query: str, pool: list) -> list[tuple[float, int, dict]]:
        q_tok = _tokenize_adaptive(query)
        result = [
            (_jaccard(q_tok, ex["tokens"]), idx, ex)
            for idx, ex in enumerate(pool)
        ]
        result.sort(key=lambda x: (x[0], x[1]), reverse=True)
        return result

    def _confusion_targets_for(self, labels: list[str]) -> list[str]:
        label_set = set(labels)
        counts: dict[str, float] = defaultdict(float)
        for lbl in labels:
            for actual, cnt in self.confusion.get(lbl, {}).items():
                if actual not in label_set:
                    counts[actual] += cnt
        return [lbl for lbl, _ in sorted(counts.items(), key=lambda x: (-x[1], x[0]))]

    def _build_parts(self, query: str) -> list[str]:
        if not self.examples:
            return []

        q_tok = _tokenize_adaptive(query)
        parts: list[str] = []
        used_ids: set[int] = set()
        total_chars = 0

        def try_add(ex: dict) -> bool:
            nonlocal total_chars
            eid = id(ex)
            if eid in used_ids:
                return False
            q = ex.get("raw_question", ex["input"])
            part = f"Q: {q}\nA: {ex['target']}"
            if total_chars + len(part) + 2 > MAX_CHARS:
                return False
            parts.append(part)
            used_ids.add(eid)
            total_chars += len(part) + 2
            return True

        # Phase 1: similarity-gated hard buffer injection
        hard_scored = sorted(
            self._hard,
            key=lambda e: _jaccard(q_tok, e["tokens"]),
            reverse=True,
        )
        hard_added = 0
        for ex in hard_scored:
            if hard_added >= _HARD_SLOTS:
                break
            sim = _jaccard(q_tok, ex["tokens"])
            if sim < _HARD_SIM_THRESHOLD:
                break
            if try_add(ex):
                hard_added += 1

        # Phase 2: confusion disambiguation (same as baseline)
        ranked = self._scored(query, self.examples)
        top_labels = [ex["target"] for _, _, ex in ranked[:_TOP_CANDIDATE_LABELS]]
        confused_with = self._confusion_targets_for(top_labels)

        if confused_with:
            disambig_labels = set(confused_with[:_TOP_CANDIDATE_LABELS])
            per_label: dict[str, list] = defaultdict(list)
            for score, idx, ex in ranked:
                if ex["target"] in disambig_labels:
                    per_label[ex["target"]].append((score, idx, ex))
            for _round in range(_DISAMBIG_PER_CONFUSION):
                for lbl in confused_with[:_TOP_CANDIDATE_LABELS]:
                    for _, _, ex in per_label.get(lbl, []):
                        if id(ex) not in used_ids:
                            try_add(ex)
                            break

        # Phase 3: fill remaining budget from general pool
        for _, _, ex in ranked:
            if total_chars >= MAX_CHARS:
                break
            try_add(ex)

        return parts

    # ------------------------------------------------------------------
    # MemorySystem interface
    # ------------------------------------------------------------------

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        parts = self._build_parts(input)
        prompt = PROMPT_TEMPLATE.format(
            examples_section="\n\n".join(parts),
            input=input,
        )
        response = self.call_llm(prompt)
        answer = extract_json_field(response, "final_answer")
        return answer, {
            "full_response": response,
            "num_examples": len(self.examples),
            "num_hard": len(self._hard),
            "num_selected": len(parts),
        }

    def _decay_confusion(self) -> None:
        to_del_outer = []
        for pred, actuals in self.confusion.items():
            to_del_inner = [a for a, c in actuals.items() if c * _DECAY_FACTOR < _PRUNE_THRESHOLD]
            for a in to_del_inner:
                del actuals[a]
            for a in actuals:
                actuals[a] *= _DECAY_FACTOR
            if not actuals:
                to_del_outer.append(pred)
        for pred in to_del_outer:
            del self.confusion[pred]

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for r in batch_results:
            raw_q = r.get("raw_question", r["input"])
            ex: dict[str, Any] = {
                "input": r["input"],
                "target": r["ground_truth"],
                "tokens": _tokenize_adaptive(raw_q),
            }
            if "raw_question" in r:
                ex["raw_question"] = r["raw_question"]
            self.examples.append(ex)

            if not r.get("was_correct", True):
                # Add to hard buffer (FIFO)
                self._hard.append(ex)
                if len(self._hard) > _HARD_BUFFER_SIZE:
                    self._hard.pop(0)
                # Update confusion matrix
                pred = _normalize_prediction(r.get("prediction", ""))
                gt = r["ground_truth"]
                if pred and pred != gt:
                    self.confusion[pred][gt] += 1.0

        self._decay_confusion()

    def get_state(self) -> str:
        serialisable = [
            {k: (sorted(v) if isinstance(v, frozenset) else v) for k, v in ex.items()}
            for ex in self.examples
        ]
        hard_serialisable = [
            {k: (sorted(v) if isinstance(v, frozenset) else v) for k, v in ex.items()}
            for ex in self._hard
        ]
        confusion_plain = {k: dict(v) for k, v in self.confusion.items()}
        return json.dumps({
            "examples": serialisable,
            "hard": hard_serialisable,
            "confusion": confusion_plain,
        }, indent=2)

    def set_state(self, state: str) -> None:
        data = json.loads(state)

        def restore_examples(lst):
            out = []
            for ex in lst:
                restored = dict(ex)
                if "tokens" in restored and isinstance(restored["tokens"], list):
                    restored["tokens"] = frozenset(restored["tokens"])
                else:
                    raw_q = restored.get("raw_question", restored.get("input", ""))
                    restored["tokens"] = _tokenize_adaptive(raw_q)
                out.append(restored)
            return out

        self.examples = restore_examples(data.get("examples", []))
        self._hard = restore_examples(data.get("hard", []))
        self.confusion = defaultdict(lambda: defaultdict(float))
        for pred, actuals in data.get("confusion", {}).items():
            for actual, cnt in actuals.items():
                self.confusion[pred][actual] = float(cnt)

"""Abstract interface for memory systems."""

import hashlib
import json
import re
import threading
from abc import ABC, abstractmethod
from typing import Any

from .llm import LLMCallable


def extract_json_field(text: str, field: str, default: str = "") -> str:
    """Helper function to extract a field from JSON in LLM response."""
    # Try direct parse
    try:
        data = json.loads(text)
        if isinstance(data, dict):
            return str(data.get(field, default))
    except json.JSONDecodeError:
        pass

    # Try code blocks: ```json ... ``` or ``` ... ```
    for match in re.finditer(r"```(?:json)?\s*([\s\S]*?)\s*```", text):
        try:
            data = json.loads(match.group(1))
            if isinstance(data, dict):
                return str(data.get(field, default))
        except json.JSONDecodeError:
            pass

    # Find balanced braces and try parsing
    for start in range(len(text)):
        if text[start] != "{":
            continue
        depth, pos, in_str = 1, start + 1, False
        while pos < len(text) and depth > 0:
            c = text[pos]
            if c == '"' and (pos == 0 or text[pos - 1] != "\\"):
                in_str = not in_str
            elif not in_str:
                depth += 1 if c == "{" else (-1 if c == "}" else 0)
            pos += 1
        if depth == 0:
            candidate = text[start:pos]
            candidate = re.sub(
                r",\s*([\]}])", r"\1", candidate
            )  # Remove trailing commas
            try:
                data = json.loads(candidate)
                if isinstance(data, dict):
                    return str(data.get(field, default))
            except json.JSONDecodeError:
                pass

    # Regex fallback
    match = re.findall(rf'"{field}"\s*:\s*"([^"]*)"', text)
    return match[-1] if match else default


class MemorySystem(ABC):
    """Memory system interface for online and offline learning.

    Args:
        llm: Callable that takes a prompt string and returns a response string.
    """

    def __init__(self, llm: LLMCallable):
        self._llm = llm
        self._prompt_local = threading.local()

    def call_llm(self, prompt: str) -> str:
        """Call the LLM with a prompt. Tracks last prompt length/hash per thread."""
        self._prompt_local.last_prompt_len = len(prompt)
        self._prompt_local.last_prompt_hash = hashlib.md5(prompt.encode()).hexdigest()[
            :8
        ]
        self._prompt_local.last_prompt_text = prompt
        return self._llm(prompt)

    def get_last_prompt_info(self) -> dict[str, Any]:
        """Return length, hash, and full text of the last prompt sent via call_llm (thread-local)."""
        return {
            "prompt_len": getattr(self._prompt_local, "last_prompt_len", None),
            "prompt_hash": getattr(self._prompt_local, "last_prompt_hash", None),
            "prompt_text": getattr(self._prompt_local, "last_prompt_text", None),
        }

    @abstractmethod
    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        """Generate prediction BEFORE seeing ground truth. Returns (answer, metadata)."""
        pass

    @abstractmethod
    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        """Learn from a batch of evaluation results.

        Args:
            batch_results: List of dicts, each containing:
                - input: str
                - prediction: str
                - ground_truth: str
                - was_correct: bool
                - metadata: dict (optional)

        This is called AFTER all predictions in the batch are complete.
        The memory system can analyze patterns across the batch.
        """
        pass

    def get_context_length(self) -> int:
        """Return the character length of context actually injected per query.

        Override in subclasses where the injected context differs from stored state
        (e.g., fewshot memories that store all examples but only inject N).
        """
        return len(self.get_state())

    @abstractmethod
    def get_state(self) -> str:
        """Return serializable state for checkpointing."""
        pass

    @abstractmethod
    def set_state(self, state: str) -> None:
        """Restore state from serialized representation."""
        pass

